 {renamingPhoto&&<div className="fixed inset-0 z-[85] flex items-center justify-center bg-slate-950/55 px-4 py-6 backdrop-blur-sm" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget&&!renameBusy){setRenamingPhoto(null);setNewPhotoName("");}}}><section role="dialog" aria-modal="true" aria-labelledby="rename-photo-title" className="w-full max-w-md rounded-3xl border border-white/60 bg-white p-6 shadow-2xl"><div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-blue-50 text-blue-600"><Pencil size={24}/></div><h2 id="rename-photo-title" className="mt-4 text-center text-xl font-bold text-slate-900">Renomear fotografia</h2><p className="mt-2 text-center text-sm text-slate-500">Altera o nome apresentado no APCLOUD. O ficheiro original permanece guardado.</p><label htmlFor="photo-new-name" className="mt-5 block text-sm font-semibold text-slate-700">Novo nome</label><input id="photo-new-name" autoFocus maxLength={255} value={newPhotoName} onChange={e=>setNewPhotoName(e.target.value)} onKeyDown={e=>{if(e.key==="Enter")void renamePhoto();if(e.key==="Escape"&&!renameBusy){setRenamingPhoto(null);setNewPhotoName("");}}} className="mt-2 min-h-12 w-full rounded-xl border border-slate-200 px-4 text-sm outline-none focus:border-blue-400 focus:ring-4 focus:ring-blue-50"/><div className="mt-6 grid grid-cols-2 gap-3"><button disabled={renameBusy} onClick={()=>{setRenamingPhoto(null);setNewPhotoName("");}} className="min-h-12 rounded-xl border border-slate-200 px-4 py-3 text-sm font-semibold text-slate-700">Cancelar</button><button disabled={renameBusy||!newPhotoName.trim()} onClick={()=>void renamePhoto()} className="inline-flex min-h-12 items-center justify-center gap-2 rounded-xl bg-blue-600 px-4 py-3 text-sm font-semibold text-white disabled:opacity-50">{renameBusy?<LoaderCircle size={17} className="animate-spin"/>:<CheckCircle2 size={17}/>} Guardar nome</button></div></section></div>}
 {albumDialog&&<div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/50 px-4 py-6 backdrop-blur-sm" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget&&!albumBusy){setAlbumDialog(false);setEditingAlbum(null);}}}><section role="dialog" aria-modal="true" aria-labelledby="album-dialog-title" className="w-full max-w-md rounded-3xl bg-white p-6 shadow-2xl"><div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-blue-50 text-blue-600"><FolderPlus size={25}/></div><h2 id="album-dialog-title" className="mt-4 text-center text-xl font-bold text-slate-900">{editingAlbum?"Renomear álbum":"Criar novo álbum"}</h2><p className="mt-2 text-center text-sm text-slate-500">Dá um nome à coleção para organizares as tuas fotografias.</p><label className="mt-5 block text-sm font-semibold text-slate-700" htmlFor="album-name">Nome do álbum</label><input id="album-name" autoFocus maxLength={120} value={albumName} onChange={e=>setAlbumName(e.target.value)} onKeyDown={e=>{if(e.key==="Enter")void saveAlbum();}} placeholder="Ex.: Família, Viagens, Trabalho" className="mt-2 min-h-12 w-full rounded-xl border border-slate-200 px-4 text-sm outline-none focus:border-blue-400 focus:ring-4 focus:ring-blue-50"/><div className="mt-6 grid grid-cols-2 gap-3"><button disabled={albumBusy} onClick={()=>{setAlbumDialog(false);setEditingAlbum(null);}} className="min-h-12 rounded-xl border border-slate-200 px-4 py-3 text-sm font-semibold text-slate-700 hover:bg-slate-50">Cancelar</button><button disabled={albumBusy||!albumName.trim()} onClick={()=>void saveAlbum()} className="inline-flex min-h-12 items-center justify-center gap-2 rounded-xl bg-blue-600 px-4 py-3 text-sm font-semibold text-white hover:bg-blue-700 disabled:opacity-50">{albumBusy?<LoaderCircle size={17} className="animate-spin"/>:<FolderPlus size={17}/>} {editingAlbum?"Guardar":"Criar álbum"}</button></div></section></div>}
